let creationMode='template',fileAsset='',fileName='',fileRevision=0,readingFile=false,uploadPreviewKey='';
const baseFormData=formData,basePreview=updatePublishPreview,baseSubmit=publishForm.onsubmit;
document.querySelector('#publish-heading').textContent='一个小想法，就可以开始。';
publishDialog.querySelector('h2+p').textContent='描述一个想法，或者把手边的文件变成可交互的 Slice。';
document.querySelector('.publish-notice').textContent='本机原型 · 文件仅在当前浏览器中读取和保存，不上传服务器；刷新后仍保留，其他用户暂不可见。';
const modes=document.createElement('div');modes.className='creation-modes';modes.setAttribute('role','group');modes.setAttribute('aria-label','创作方式');modes.innerHTML='<button type="button" data-mode="template" aria-pressed="true"><strong>✳ 模板轻创作</strong><span>选一个切片，写下想法</span></button><button type="button" data-mode="image" aria-pressed="false"><strong>▧ 图片 + 互动</strong><span>上传图片，点击揭晓故事</span></button><button type="button" data-mode="html" aria-pressed="false"><strong>↥ 上传 HTML</strong><span>带来已经做好的交互Slice</span></button>';publishForm.before(modes);
const uploadFields=document.createElement('div');uploadFields.id='file-section';uploadFields.hidden=true;uploadFields.innerHTML=`<label class="drop-zone" id="drop-zone"><span class="upload-icon">↥</span><strong>拖放文件，或点击选择</strong><span id="upload-hint"></span><input id="work-file" type="file" aria-label="选择Slice文件"></label><div id="file-info" role="status"></div><div id="html-help" hidden><p class="field-help">单个 HTML / HTM，最大 300 KB，内含 CSS 和 JavaScript。外部资源、联网请求和 ZIP 暂不支持。</p><a class="sample-link" href="sample-interactive.html" download="我的色彩实验.html">↓ 下载示例 HTML</a><button type="button" id="load-example">先用示例体验</button></div><div id="image-options" hidden><label>按钮文案 <input name="buttonText" maxlength="24" value="点击揭晓"></label><label>点击后展示什么？ <textarea name="reveal" maxlength="300" rows="3" placeholder="写下一个答案、故事或小发现"></textarea></label><span class="field-help">PNG / JPG / WEBP，最大 2 MB。上传图片、写文案，就能做一个互动切片。</span></div>`;
document.querySelector('.publish-fields').prepend(uploadFields);const templateLabel=publishForm.elements.template.closest('label');const oldHelp=templateLabel.nextElementSibling;oldHelp.textContent='从六个可玩的模板开始，不需要编写代码。';
formData=function(){return {...baseFormData(),assetType:creationMode==='template'?null:creationMode,asset:creationMode==='template'?'':fileAsset,fileName,buttonText:publishForm.elements.buttonText.value.trim(),reveal:publishForm.elements.reveal.value.trim()}};
updatePublishPreview=function(reset=false){if(creationMode==='template'){basePreview(reset);return}const d=formData();document.querySelector('#preview-title').textContent=d.title||'你的下一个好想法';document.querySelector('#preview-desc').textContent=d.desc||'写下一句话介绍，让人忍不住试一下。';document.querySelector('#preview-author').textContent=d.author||'好奇心Slicer';const key=[creationMode,fileRevision,d.buttonText,d.reveal].join('|');if(!reset&&key===uploadPreviewKey)return;uploadPreviewKey=key;const host=document.querySelector('#publish-slice');host.dataset.template='';host.innerHTML=fileAsset?importedStage(d):'<div class="upload-empty"><span>↥</span><strong>你的Slice，将从这里开始</strong><p>选择文件后即可在这里试玩</p></div>'};
function setCreationMode(mode,clear=true){creationMode=mode;if(clear){fileAsset='';fileName='';fileRevision++;readingFile=false;document.querySelector('#work-file').value=''}document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));uploadFields.hidden=mode==='template';templateLabel.hidden=mode!=='template';oldHelp.hidden=mode!=='template';document.querySelector('#image-options').hidden=mode!=='image';document.querySelector('#html-help').hidden=mode!=='html';document.querySelector('#work-file').accept=mode==='html'?'.html,.htm':'image/png,image/jpeg,image/webp';document.querySelector('#upload-hint').textContent=mode==='html'?'HTML / HTM · 单文件互动Slice':'PNG / JPG / WEBP · 图片变成一个小发现';document.querySelector('#file-info').textContent=fileName?'已选择：'+fileName:'';document.querySelector('#publish-error').textContent='';updatePublishPreview(true)}
function openCreator(work){const d=work||readStored(draftKey,null);if(d){for(const [name,key] of [['title','title'],['description','desc'],['category','cat'],['template','template'],['author','author'],['buttonText','buttonText'],['reveal','reveal']])if(typeof d[key]==='string')publishForm.elements[name].value=d[key];fileAsset=typeof d.asset==='string'?d.asset:'';fileName=typeof d.fileName==='string'?d.fileName:'';fileRevision++;setCreationMode(['html','image'].includes(d.assetType)?d.assetType:'template',false)}if(!publishDialog.open)publishDialog.showModal();updatePublishPreview(true);document.querySelector('#publish-error').textContent=''}
document.querySelector('#publish-entry').onclick=()=>openCreator();document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mode!==creationMode)setCreationMode(b.dataset.mode)});
async function importFile(file){if(!file)return;const mode=creationMode,revision=++fileRevision;readingFile=true;document.querySelector('#publish-error').textContent='';document.querySelector('#file-info').textContent='正在读取 '+file.name+'…';try{if(file.size>(mode==='html'?300*1024:2*1024*1024))throw Error(mode==='html'?'HTML 文件不能超过 300 KB。':'图片不能超过 2 MB，请压缩后重试。');if(!file.size)throw Error('这个文件是空的，请换一个文件。');let data;if(mode==='html'){if(!/\.html?$/i.test(file.name))throw Error('请选择单个 .html 或 .htm 文件，暂不支持 ZIP。');data=await file.text();if(!/<[a-z][\s\S]*>/i.test(data))throw Error('没有识别到 HTML 内容，请检查文件。')}else{if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择 PNG、JPG 或 WEBP 图片。');data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('文件读取失败，请重新选择。'));reader.readAsDataURL(file)});const img=new Image();img.src=data;await img.decode().catch(()=>{throw Error('图片无法打开，请检查文件是否完整。')})}if(revision!==fileRevision||mode!==creationMode)return;fileAsset=data;fileName=file.name;document.querySelector('#file-info').textContent='✓ '+file.name+' · '+Math.max(1,Math.round(file.size/1024))+' KB';if(!publishForm.elements.title.value)publishForm.elements.title.value=file.name.replace(/\.[^.]+$/,'').slice(0,50);updatePublishPreview(true)}catch(err){if(revision===fileRevision){document.querySelector('#publish-error').textContent=err.message;document.querySelector('#file-info').textContent=fileName?'仍使用：'+fileName:'尚未选择文件'}}finally{if(revision===fileRevision)readingFile=false}}
document.querySelector('#work-file').onchange=e=>importFile(e.target.files[0]);const drop=document.querySelector('#drop-zone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');if(e.dataTransfer.files.length!==1){document.querySelector('#publish-error').textContent='请一次选择一个文件。';return}importFile(e.dataTransfer.files[0])};
const exampleHtml=`<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><style>body{margin:0;min-height:100vh;display:grid;place-content:center;text-align:center;background:#dfff85;color:#182517;font:16px system-ui}button{border:0;border-radius:30px;padding:14px 24px;background:#182517;color:white;font:inherit;cursor:pointer}h1{font-size:28px;margin:10px}p{margin:12px 0 24px}</style><body><p>COLOR PLAYGROUND</p><h1>今天，你是什么颜色？</h1><p id="answer">点击一下，发现新的心情。</p><button onclick="let a=['灵感绿','日落橙','海洋蓝','莓果粉'];let c=['#dfff85','#ffcf9b','#b2e2f5','#f5c2dc'];let i=Math.floor(Math.random()*4);document.body.style.background=c[i];document.getElementById('answer').textContent=a[i]">换一种心情 ↗</button></body></html>`;
document.querySelector('#load-example').onclick=()=>{fileAsset=exampleHtml;fileName='我的色彩实验.html';fileRevision++;readingFile=false;publishForm.elements.title.value='今天，你是什么颜色？';publishForm.elements.description.value='轻轻点击，给今天换一种心情。';publishForm.elements.category.value='Creative';document.querySelector('#file-info').textContent='✓ 已加载示例：'+fileName;document.querySelector('#publish-error').textContent='';updatePublishPreview(true)};
const saveDraft=document.querySelector('#save-draft').onclick;document.querySelector('#save-draft').onclick=()=>{if(readingFile){document.querySelector('#publish-error').textContent='请等待文件读取完成。';return}saveDraft()};
publishForm.onsubmit=e=>{const d=formData();let error='';if(readingFile)error='请等待文件读取完成。';else if(d.assetType&&!d.asset)error='请先选择文件，或使用示例体验。';else if(d.assetType==='image'&&!d.reveal)error='请写下点击后要展示的内容。';if(error){e.preventDefault();document.querySelector('#publish-error').textContent=error;return}baseSubmit(e);if(!publishDialog.open)setCreationMode('template')};
const requestedCreation=new URLSearchParams(location.search).get('create');if(['template','image','html'].includes(requestedCreation)){openCreator();setCreationMode(requestedCreation)}
